import express from 'express';
import multer from 'multer';
import path from 'path';
import fs from 'fs';
import crypto from 'crypto';
import { execSync } from 'child_process';

const app = express();
const upload = multer({ dest: '/tmp/uploads/' });

// Document conversion endpoint - converts uploaded docs to PDF
app.post('/api/v2/convert', upload.single('document'), async (req, res) => {
  try {
    if (!req.file) {
      return res.status(400).json({ error: 'No file provided' });
    }

    const allowedMimes = ['application/msword', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
      'application/vnd.oasis.opendocument.text', 'text/rtf', 'text/plain'];

    // Check MIME type from multer
    if (!allowedMimes.includes(req.file.mimetype)) {
      fs.unlinkSync(req.file.path);
      return res.status(415).json({ error: 'Unsupported file type' });
    }

    const outputId = crypto.randomBytes(16).toString('hex');
    const outputPath = `/tmp/converted/${outputId}.pdf`;

    // Sanitize original filename for use in output metadata
    const safeBasename = path.basename(req.file.originalname).replace(/[^a-zA-Z0-9._-]/g, '_');

    // Use LibreOffice for conversion with custom output filename
    const inputPath = req.file.path;
    const loCommand = `soffice --headless --convert-to pdf --outdir /tmp/converted/ "${inputPath}"`;

    execSync(loCommand, { timeout: 30000, encoding: 'utf-8' });

    // LibreOffice outputs with same basename, rename to our ID
    const loOutput = `/tmp/converted/${path.basename(inputPath)}.pdf`;
    if (fs.existsSync(loOutput)) {
      fs.renameSync(loOutput, outputPath);
    }

    // Post-processing: add metadata using exiftool
    const title = req.body.title || safeBasename;
    const author = req.body.author || 'System';

    // Apply PDF metadata
    const metaCmd = `exiftool -Title="${title}" -Author="${author}" -overwrite_original "${outputPath}"`;
    execSync(metaCmd, { timeout: 10000, encoding: 'utf-8' });

    // Cleanup input
    fs.unlinkSync(inputPath);

    res.json({
      id: outputId,
      filename: `${safeBasename}.pdf`,
      download_url: `/api/v2/download/${outputId}`
    });
  } catch (err) {
    console.error('Conversion failed:', err.message);
    if (req.file && fs.existsSync(req.file.path)) {
      fs.unlinkSync(req.file.path);
    }
    res.status(500).json({ error: 'Conversion failed' });
  }
});

app.get('/api/v2/download/:id', (req, res) => {
  const id = req.params.id.replace(/[^a-f0-9]/g, '');
  const filePath = `/tmp/converted/${id}.pdf`;
  if (fs.existsSync(filePath)) {
    res.download(filePath);
  } else {
    res.status(404).json({ error: 'File not found' });
  }
});

app.get('/health', (req, res) => res.json({ status: 'ok' }));

app.listen(process.env.PORT || 3000);
